UPDATE portfolios
   SET title         = #{p.title},
       introduction  = #{p.introduction},
       contact_email = #{p.contactEmail},
       contact_url   = #{p.contactUrl},
       is_public     = #{p.isPublic},
       published_at  = #{p.publishedAt}
 WHERE id = #{p.portfolioId}
   AND streamer_id = #{p.streamerId}

